// this was the first time the task was executed; no rows otherwise. The
// analytics task_executed event fires exactly when this returns a row —
// retries and re-assignments hit the WHERE clause and no-op.
func (q *Queries) MarkTaskFirstExecuted(ctx context.Context, id pgtype.UUID) (MarkTaskFirstExecutedRow, error) {
	row := q.db.QueryRow(ctx, markTaskFirstExecuted, id)
	var i MarkTaskFirstExecutedRow
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.CreatorType,
		&i.CreatorID,
		&i.FirstExecutedAt,
	)
	return i, err
}

